    rmin, cmin = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-rmin, c-cmin) for r, c in pts]
    dh = max(r for r, c in shape)
    dw = max(c for r, c in shape)

    out = [row[:] for row in grid]
    # The seed pattern is copied over matching empty locations; background
    # cells within a translated pattern are left untouched.
    for r0 in range(h-dh):
        for c0 in range(w-dw):
            cells = [(r0+dr, c0+dc) for dr, dc in shape]
            empty = [(r, c) for r, c in cells if grid[r][c] == 0]
            if len(empty) >= 2 and all(grid[r][c] in (0, color) for r, c in cells):
                for r, c in empty:
                    out[r][c] = color
    return out
